import {STRUCT_STATUS_FLAGS} from "../constants/StructConstants";

export class Struct {
  constructor() {
    /** @type {string|null} */
    this.id = null;

    /** @type {number|null} */
    this.index = null;

    /** @type {number|null} - FK to struct_type.id */
    this.type = null;

    /** @type {string|null} */
    this.creator = null;

    /** @type {string|null} - Player ID who owns this struct */
    this.owner = null;

    /** @type {string|null} - "fleet" or "planet" */
    this.location_type = null;

    /** @type {string|null} - Fleet ID or Planet ID */
    this.location_id = null;

    /** @type {string|null} - "space", "air", "land", "water" */
    this.operating_ambit = null;

    /** @type {number|null} */
    this.slot = null;

    /** @type {number|null} */
    this.health = null;

    /** @type {number|null} */
    this.status = null;

    /** @type {string|null} the ID of the struct that this struct is protecting => */
    this.protected_struct_id = null;

    /** @type {string[]} the IDs of the structs that are defending this struct <=> */
    this.defending_struct_ids = [];

    /** @type {number|null} */
    this.destroyed_block = null;

    /** @type {number|null} amount of alpha infused in the struct (legacy display grams) */
    this.fuel = null;

    /** @type {bigint|null} ualpha infused in the struct */
    this.fuel_p = null;

    /** @type {bigint|null} milliwatts of generator capacity */
    this.generator_capacity_p = null;
  }

  /**
   * @return {boolean}
   */
  isMaterialized() {
    return (this.status & STRUCT_STATUS_FLAGS.MATERIALIZED) > 0;
  }

  /**
   * @return {boolean}
   */
  isBuilt() {
    return (this.status & STRUCT_STATUS_FLAGS.BUILT) > 0;
  }

  /**
   * @return {boolean}
   */
  isOnline() {
    return (this.status & STRUCT_STATUS_FLAGS.ONLINE) > 0;
  }

  /**
   * @return {boolean}
   */
  isStored() {
    return (this.status & STRUCT_STATUS_FLAGS.STORED) > 0;
  }

  /**
   * @return {boolean}
   */
  isDefending() {
    return !!this.protected_struct_id;
  }

  /**
   * @return {boolean}
   */
  isDefended() {
    return this.defending_struct_ids.length > 0;
  }

  /**
   * @return {boolean}
   */
  isHidden() {
    return (this.status & STRUCT_STATUS_FLAGS.HIDDEN) > 0;
  }

  /**
   * @return {boolean}
   */
  isDestroyed() {
    return (this.status & STRUCT_STATUS_FLAGS.DESTROYED) > 0;
  }

  /**
   * @return {boolean}
   */
  isLocked() {
    return (this.status & STRUCT_STATUS_FLAGS.LOCKED) > 0;
  }

  /**
   * @param {number} flag see STRUCT_STATUS_FLAGS
   */
  addStatusFlag(flag) {
    this.status |= flag;
  }

  /**
   * @param {number} flag see STRUCT_STATUS_FLAGS
   */
  removeStatusFlag(flag) {
    this.status &= ~flag;
  }
}

